package com.jono.app;
import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.google.firebase.auth.FirebaseAuth; import com.google.firebase.firestore.*; import java.util.HashMap; import java.util.Map;
public class CreatePostActivity extends AppCompatActivity { EditText text; public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,48,24,24);TextView t=new TextView(this);t.setText("Create Post");t.setTextSize(26);text=new EditText(this);text.setHint("What's on your mind?");text.setMinLines(5);Button p=new Button(this);p.setText("Publish");l.addView(t);l.addView(text);l.addView(p);setContentView(l);p.setOnClickListener(v->{if(FirebaseAuth.getInstance().getCurrentUser()==null){Toast.makeText(this,"Please login first",Toast.LENGTH_SHORT).show();return;}Map<String,Object> post=new HashMap<>();post.put("authorId",FirebaseAuth.getInstance().getCurrentUser().getUid());post.put("text",text.getText().toString());post.put("visibility","public");post.put("likesCount",0);post.put("commentsCount",0);post.put("sharesCount",0);post.put("createdAt",FieldValue.serverTimestamp());FirebaseFirestore.getInstance().collection("posts").add(post).addOnSuccessListener(x->finish());});}}
